// Real-GPU golden E2E of the real-weight EmbeddingGemma-300m (sentence embedding) (step 3 of
// ADR 0005).
//
// The tiny golden (tests/e2e_golden_test.ts) covers "the op contracts" and the real-weight SBV2
// (tests/e2e_sbv2_test.ts) covers "real weights on the acoustic chain"; this file covers **a
// real-weight text model with a single vector output**. The target is
// `outputs/series/embeddinggemma-300m/` (weights of about 1.2 GB, so outside the repository —
// `outputs/` in `.gitignore`). It is generated by `tools/export-recipes/embeddinggemma/export.py`
// (the GENERATE_COMMAND below is the source of truth for the command).
//
// Unlike SBV2 there is only one storage dtype series, f32 (f16 / i8 are a matter for separate
// series — the exporter's opening docstring), so the series is not parameterised. The graph has no
// target split either, just one (Transformer → masked mean → Dense×2 → L2 normalisation), and the
// directory layout is flat too:
// `outputs/series/embeddinggemma-300m/{model-NNNNN-of-NNNNN.krm,io.<case>.safetensors}`.
//
// Where the asset is missing the cases **SKIP explicitly**. ADR 0005's "an all-SKIP run is an
// explicit FAIL" guard (tests/gpu_gate_test.ts) looks only at *whether a GPU adapter exists* and
// is independent of this SKIP. Conversely, an asset that exists **only partly** (missing cases)
// FAILs rather than SKIPs (the "asset completeness" test below) — there a SKIP would be a silent
// apparent success.
//
// EmbeddingGemma has no published distribution yet, so every case here is an implementation-time
// series check (ADR 0139 decision 6): it runs only with KARUME_SERIES=1 and SKIPs explicitly
// otherwise.
//
// NOTE: EmbeddingGemma gets a published distribution (ADR 0139 Rulings D2, staging step 7). The
// container then comes from `models/<repo>/` through the manifest (`helpers/mirror.ts`) and the
// io.* goldens from `goldenDir("embeddinggemma-300m")`, and these cases return to the default lane.

import { type DirEntry, isNotFound, readDirSync, readFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals } from "@std/assert";
import { acquireGpu, parseSafetensors, prepareContainer, type Tensor } from "../../runtime/mod.ts";
import {
  compareTensors,
  formatAllclose,
  type Tolerance,
} from "../../runtime/src/reference/allclose.ts";
import { assertAdapterMatchesEnvironment } from "../../runtime/tests/helpers/environment.ts";
import { ioTensor } from "../../runtime/tests/helpers/golden-io.ts";
import { GPU_AVAILABLE } from "../../runtime/tests/helpers/gpu.ts";
import { openResults, runRecordedCase } from "../../runtime/tests/helpers/results.ts";
import { modelPresent, openSeriesContainer } from "../../runtime/tests/helpers/container-files.ts";
import { seriesGraph } from "../../models/tests/helpers/series-graphs.ts";
import { SERIES_CHECKS, SERIES_CHECKS_OPT_IN } from "../../models/tests/helpers/series-checks.ts";

/**
 * The tolerance for comparing the real-weight EmbeddingGemma-300m against the torch CPU
 * expectations.
 *
 * Measured (plain comparison with `atol=rtol=0`, 5 cases × one output `[1,768]`):
 *
 * | Case          | T   | maxAbs  | maxRel  | \|ref\| max | \|ref\| min non-zero |
 * | ------------- | --- | ------- | ------- | ----------- | -------------------- |
 * | query-en      | 16  | 2.31e-7 | 3.91e-4 | 0.172       | 7.63e-5              |
 * | document-en   | 19  | 2.83e-7 | 8.41e-4 | 0.249       | 5.79e-5              |
 * | query-ja      | 16  | 2.83e-7 | 6.82e-4 | 0.181       | 9.37e-5              |
 * | bare          | 12  | 2.76e-7 | 1.65e-3 | 0.170       | 2.98e-5              |
 * | long-document | 318 | 3.87e-7 | 3.87e-4 | 0.156       | 6.64e-5              |
 *
 * **As with the tiny golden (`GOLDEN_TOLERANCE`), atol drives the verdict** (`|x−y| ≤ atol +
 * rtol·|ref|`): the output is an L2-normalised unit vector whose values thin out down to near 0
 * (the \|ref\| min non-zero goes down to 2.98e-5), so maxRel grows to 1.65e-3 there, but the
 * absolute error of that element is only `1.65e-3 × 2.98e-5 ≈ 4.9e-8`. Even at the \|ref\| max of
 * 0.249 the rtol contribution is `1e-5 × 0.249 ≈ 2.5e-6`, about 1/4 of atol, and does not drive
 * the verdict.
 *
 * atol 1e-6 is about 2.6 times the measured worst case of 3.87e-7 (long-document). **That it equals
 * the tiny golden's `GOLDEN_TOLERANCE` is a coincidence of independent measurements, not reuse**
 * (the same reason SBV2 dp's `SBV2_TOLERANCE` came out at the same value — this model's own
 * measurement fell inside it). The sources of error are the same too (fma fusion, a reduction
 * order of matmul / masked mean that differs from torch, implementation differences in
 * transcendental functions (the sqrt / rsqrt family)): with the Transformer's layer count fixed,
 * making T 26 times longer (12 → 318) grows maxAbs only about 1.7 times. The error of an
 * implementation bug (a swapped mask axis in the pooling, a wrongly transposed Dense weight, a
 * wrong normalisation denominator) is O(0.1) to O(1), the same as the output range, at least five
 * orders of magnitude above this threshold.
 */
const EMBEDDINGGEMMA_TOLERANCE: Tolerance = { atol: 1e-6, rtol: 1e-5 };

const SERIES_NAME = "embeddinggemma-300m";
const SERIES_ROOT = new URL(`../../../outputs/series/${SERIES_NAME}/`, import.meta.url);
const MODEL_FILE = "model.krm";
/**
 * The graph name inside the container (the one table in helpers/series-graphs.ts — looked up from
 * the same source of truth as the guard).
 */
const GRAPH_NAME = seriesGraph(SERIES_NAME);
const IO_PREFIX = "io.";
const IO_SUFFIX = ".safetensors";

/** The generate command a SKIP prints (the same spelling as tools/export-recipes/embeddinggemma/README.md). */
const GENERATE_COMMAND =
  "cd tools/export-recipes && uv run --with 'transformers==5.14.1' python -m embeddinggemma.export";

/**
 * The cases that should have been generated. **Pinned here rather than taken from the listing** —
 * relying on the listing alone, an environment that ran only part of the generation would lose
 * tests silently and end up "green but unchecked". The source of truth is GOLDEN_CASES in
 * `tools/exporter/export_embeddinggemma.py`.
 */
const EXPECTED_CASES = ["bare", "document-en", "long-document", "query-en", "query-ja"] as const;

/**
 * Lists the asset directory. It falls back to empty only when the directory does not exist.
 * MUST: anything but NotFound propagates — reading a permission error or the like as "no asset"
 * would turn a check that never ran into a quiet green SKIP.
 */
const listDir = (url: URL): readonly DirEntry[] => {
  try {
    return [...readDirSync(url)];
  } catch (cause) {
    if (isNotFound(cause)) {
      return [];
    }
    throw cause;
  }
};

const discoverCases = (root: URL): readonly string[] =>
  listDir(root)
    .filter(
      (entry) => entry.isFile && entry.name.startsWith(IO_PREFIX) && entry.name.endsWith(IO_SUFFIX),
    )
    .map((entry) => entry.name.slice(IO_PREFIX.length, entry.name.length - IO_SUFFIX.length))
    .sort();

const readBuffer = async (root: URL, file: string): Promise<ArrayBuffer> => {
  const bytes = await readFile(new URL(file, root));
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
};

/**
 * Listed synchronously because it is needed at registration (the same reason as Deno.test's ignore
 * decision). Without KARUME_SERIES=1 the series is not read: the expected cases are registered as
 * explicit SKIPs.
 */
const CASES = SERIES_CHECKS ? discoverCases(SERIES_ROOT) : EXPECTED_CASES;
/**
 * Whether the asset exists. None at all = an environment that has not generated it, so every case
 * SKIPs (a partial gap goes to the FAIL side).
 */
const AVAILABLE = SERIES_CHECKS && CASES.length > 0;
/**
 * Whether **anything at all** is left (the SKIP predicate of the completeness test — Codex round H
 * finding H-02). A gap where every io is gone and only the model remains makes `AVAILABLE` false,
 * and with `ignore: !AVAILABLE` the completeness test itself would SKIP — the predicate that turns
 * a gap into a FAIL may stay dormant only when the directory is "completely empty".
 */
const ANY_PRESENT = SERIES_CHECKS && (AVAILABLE || modelPresent(new URL(MODEL_FILE, SERIES_ROOT)));

if (SERIES_CHECKS && !AVAILABLE) {
  console.warn(
    `[karume] ${SERIES_ROOT.pathname} has no exported asset, so the real-weight EmbeddingGemma E2E is ` +
      `SKIPPED (weights of about 1.2 GB, kept outside the repository). Generate: ${GENERATE_COMMAND}`,
  );
}

test.skipIf(!ANY_PRESENT)(
  `EmbeddingGemma asset: the expected cases and the model itself are all present${SERIES_CHECKS_OPT_IN}`,
  () => {
    assertEquals(CASES, [...EXPECTED_CASES], `golden cases of ${SERIES_ROOT.pathname}`);
    assert(modelPresent(new URL(MODEL_FILE, SERIES_ROOT)), `${MODEL_FILE} is missing`);
  },
);

/**
 * Where the settlements and measurements go
 * (`outputs/verify/<environment key>/<date>_embeddinggemma-golden/` — safe to delete).
 *
 * The series is named `<family>-golden` because the models-side e2e writes to the same root under
 * the bare family name (two modules writing to the same folder overwrite each other's `cases`).
 */
const results = openResults("embeddinggemma-golden");

for (const caseName of CASES) {
  test.skipIf(!AVAILABLE || !GPU_AVAILABLE)(
    `EmbeddingGemma golden comparison: ${caseName} (real GPU / torch CPU expectations)${SERIES_CHECKS_OPT_IN}`,
    async () => {
      await runRecordedCase(results, { id: caseName }, async ({ measurements }) => {
        const [opened, ioBytes] = await Promise.all([
          openSeriesContainer(new URL(MODEL_FILE, SERIES_ROOT)),
          readBuffer(SERIES_ROOT, `${IO_PREFIX}${caseName}${IO_SUFFIX}`),
        ]);
        const parsed = prepareContainer(opened, GRAPH_NAME);
        const io = parseSafetensors(ioBytes);

        // Every tensor of io matches the graph's inputs and outputs exactly (nothing extra,
        // nothing missing).
        const expectedKeys = [
          ...parsed.graph.inputs.map((spec) => `input.${spec.name}`),
          ...parsed.graph.outputs.map((_, index) => `output.${index}`),
        ].sort();
        assertEquals([...io.tensors.keys()].sort(), expectedKeys, "tensor keys of io.safetensors");

        // The symbolic dimension T is bound from the actual length of the golden's input shape
        // (no explicit bindings are passed). T differs per case (12 / 16 / 16 / 19 / 318), so an
        // implementation that depends on the declared upper bound Tmax = 512 (sym_max — SYM_MAX
        // in export_embeddinggemma.py), such as building the plan at Tmax, breaks a value or a
        // shape here.
        const inputs: Record<string, Tensor> = {};
        for (const spec of parsed.graph.inputs) {
          const view = io.tensors.get(`input.${spec.name}`);
          assert(view !== undefined, `input.${spec.name} is missing from the golden`);
          inputs[spec.name] = ioTensor(io, view, spec.dtype);
        }

        const gpu = await acquireGpu();
        // MUST: the device is destroyed also when the adapter check or `createSession` fails.
        // Missing that, the rest of the run carries an undestroyed device and later cases go red
        // with OOM (the delayed release in known-issues).
        try {
          // This path records reference values and results as this machine's rows, so it checks
          // here that the adapter the key was taken from is the one running (mixing them up on a
          // multi-GPU machine would measure against another machine's band).
          assertAdapterMatchesEnvironment(gpu);
          const session = await parsed.createContainerSession(gpu);
          try {
            const outputs = await session.run(inputs);
            assertEquals(Object.keys(outputs).sort(), [...parsed.graph.outputs].sort());

            parsed.graph.outputs.forEach((name, index) => {
              const view = io.tensors.get(`output.${index}`);
              assert(view !== undefined, `output.${index} is missing from the golden`);
              const where = `${caseName} output.${index} ('${name}')`;
              const declared = parsed.graph.values[name].dtype;
              assertEquals(outputs[name].shape, view.shape, `${where}: shape`);
              assertEquals(outputs[name].dtype, declared, `${where}: dtype`);
              const report = compareTensors(
                outputs[name],
                ioTensor(io, view, declared),
                EMBEDDINGGEMMA_TOLERANCE,
              );
              measurements.push({
                output: name,
                maxAbs: report.maxAbsError,
                maxRel: report.maxRelError,
                tolerance: EMBEDDINGGEMMA_TOLERANCE,
                stage: "karume",
              });
              assert(report.pass, `${where}: ${formatAllclose(report)}`);
            });
          } finally {
            await session.dispose();
          }
        } finally {
          gpu.destroy();
        }
      });
    },
  );
}
